-- หมายเหตุ: คำตอบถูกเก็บใน question_answer_keys ซึ่งไม่มี public SELECT policy

alter table public.questions add column if not exists english text;

begin;

do $seed$
declare
  v_course_id uuid;
  v_lesson_id uuid;
  v_exercise_id uuid;
  v_question_id uuid;
