    insert into public.courses (title, description, level, category, lesson_count, estimated_minutes, published)
    values ('Everyday English Path', 'เส้นทางภาษาอังกฤษจากพื้นฐานไปสู่การสื่อสารในชีวิตประจำวัน', 'Beginner–Intermediate', 'General English', 0, 250, true)
